// CP01 - Sum First N (Exclusive Bound)
// Target misconception: CPP-M01 (exclusive upper bound treated as inclusive)
//
// Contract: read n, print the sum of the integers 0 .. n-1. The upper bound n
// is exclusive. For n = 0 the range is empty and the sum is 0.
//
// This solution is the correct control. It uses `i < n`, so it iterates
// exactly n times. The variant `variants/CP01__CPP-M01a.cpp` uses `i <= n`
// and reads one item past the upper bound.
#include <iostream>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n = 0;
    if (!(std::cin >> n)) {
        return 0;
    }

    // The upper bound is exclusive. `i < n` gives exactly n iterations.
    long long total = 0;
    for (int i = 0; i < n; ++i) {
        total += i;
    }

    std::cout << total << '\n';
    return 0;
}

// CP02 - Largest Value, Not Position
// Target misconception: CPP-M02 (element value confused with index position)
//
// Contract: read n and then n integers, print the largest value. Print the
// value, not its position. For n = 0 print NONE.
//
// This solution is the correct control. It returns `best`, which holds a
// value from the vector. The variant `variants/CP02__CPP-M02a.cpp` prints
// `best_index`, which holds a position.
#include <iostream>
#include <vector>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n = 0;
    if (!(std::cin >> n)) {
        return 0;
    }

    std::vector<int> values;
    if (n > 0) {
        values.reserve(static_cast<std::size_t>(n));
        for (int i = 0; i < n; ++i) {
            int v = 0;
            if (!(std::cin >> v)) {
                return 0;
            }
            values.push_back(v);
        }
    }

    if (values.empty()) {
        std::cout << "NONE" << '\n';
        return 0;
    }

    int best = values[0];
    for (std::size_t i = 1; i < values.size(); ++i) {
        if (values[i] > best) {
            best = values[i];
        }
    }

    std::cout << best << '\n';
    return 0;
}

// CP03 - Return, Do Not Print
// Target misconception: CPP-M03 (printing treated as equivalent to returning)
//
// Contract: write `int twice(int x)` that returns x * 2. The function must
// return the value. It must not print the value. `main` reads x and prints
// twice(x) + 1.
//
// This solution is the correct control. `twice` uses a return statement. The
// variant `variants/CP03__CPP-M03a.cpp` prints inside `twice` and returns 0.
// The verifier links that variant into a separate driver to observe the
// return channel on its own.
#include <iostream>

int twice(int x) {
    // The value travels through the return channel.
    return x * 2;
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int x = 0;
    if (!(std::cin >> x)) {
        return 0;
    }

    // The expression reads the return value. It does not read printed text.
    std::cout << (twice(x) + 1) << '\n';
    return 0;
}

// CP04 - Last Element Of A Vector
// Target misconception: CPP-M04 (index equal to container size treated as valid)
//
// Contract: read n and then n integers, print the last element. For n = 0
// print EMPTY. The index size() is never a valid index.
//
// This solution is the correct control. It guards the empty vector and it
// reads the last valid index `values.size() - 1`. The variant
// `variants/CP04__CPP-M04a.cpp` reads index `values.size()`. The variant
// `variants/CP04__CPP-M04b.sanitize-only.cpp` loops with `i <= size()`.
#include <iostream>
#include <vector>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n = 0;
    if (!(std::cin >> n)) {
        return 0;
    }

    std::vector<int> values;
    if (n > 0) {
        values.reserve(static_cast<std::size_t>(n));
        for (int i = 0; i < n; ++i) {
            int v = 0;
            if (!(std::cin >> v)) {
                return 0;
            }
            values.push_back(v);
        }
    }

    if (values.empty()) {
        std::cout << "EMPTY" << '\n';
        return 0;
    }

    // The last valid index is size() - 1. Index size() is out of range.
    const std::size_t last = values.size() - 1;
    std::cout << values[last] << '\n';
    return 0;
}

// CP05 - Range Check 1 To 10
// Target misconception: CPP-M05 (misunderstanding compound boolean comparison)
//
// Contract: read x and print IN when x is inside the closed range 1 to 10.
// Print OUT otherwise. Use an explicit conjunction of two comparisons.
//
// This solution is the correct control. It uses `1 <= x && x <= 10`. The
// variant `variants/CP05__CPP-M05a.cpp` uses the mathematical chain
// `1 <= x <= 10`. In C++ that expression is `(1 <= x) <= 10`, which is always
// true, so the variant reports IN for every input.
#include <iostream>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int x = 0;
    if (!(std::cin >> x)) {
        return 0;
    }

    // Two comparisons joined by &&. Each operand is a boolean.
    if (1 <= x && x <= 10) {
        std::cout << "IN" << '\n';
    } else {
        std::cout << "OUT" << '\n';
    }
    return 0;
}

// CP06 - Zero Or Not Zero
// Target misconception: CPP-M06 (confusing assignment and equality comparison)
//
// Contract: read x and print ZERO when x equals 0. Print NONZERO otherwise.
// Compare the values. Do not assign.
//
// This solution is the correct control. The condition uses `==`. The variant
// `variants/CP06__CPP-M06a.cpp` uses `=` and always takes the else branch.
// The variant `variants/CP06__CPP-M06b.cpp` assigns to a literal and the
// compiler rejects it.
#include <iostream>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int x = 0;
    if (!(std::cin >> x)) {
        return 0;
    }

    // A comparison, not an assignment.
    if (x == 0) {
        std::cout << "ZERO" << '\n';
    } else {
        std::cout << "NONZERO" << '\n';
    }
    return 0;
}

// CP07 - Factorial By Recursion
// Target misconception: CPP-M07 (recursion or iteration fails to make progress)
//
// Contract: read n and print n factorial. Use a recursive function
// `long long factorial(int n)`. Each recursive call must approach the base
// case n <= 1.
//
// This solution is the correct control. The recursive call passes `n - 1`,
// so the state approaches the base case. The variant
// `variants/CP07__CPP-M07a.cpp` passes `n` again and never reaches the base
// case. The variant `variants/CP07__CPP-M07b.cpp` loops without updating the
// loop variable.
#include <iostream>

long long factorial(int n) {
    // Base case.
    if (n <= 1) {
        return 1;
    }
    // Each call reduces n by one. The state approaches the base case.
    return static_cast<long long>(n) * factorial(n - 1);
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n = 0;
    if (!(std::cin >> n)) {
        return 0;
    }

    std::cout << factorial(n) << '\n';
    return 0;
}

// CP08 - First Position Of A Target
// Target misconception: CPP-M08 (loop fails to update its exit condition)
//
// Contract: read n, then n integers, then a target t. Print the 0-based
// position of the first value that equals t. If t is absent, print NOT FOUND.
// The search loop must stop when the list ends.
//
// This solution is the correct control. The loop variable `i` changes on
// every iteration, and the loop stops at `values.size()`. The variant
// `variants/CP08__CPP-M08a.cpp` uses a while loop with no update. The variant
// `variants/CP08__CPP-M08b.cpp` uses a for loop with a missing update
// statement. Both pass when the target sits at index 0, and both hang when
// the target is absent.
#include <iostream>
#include <vector>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n = 0;
    if (!(std::cin >> n)) {
        return 0;
    }

    std::vector<int> values;
    if (n > 0) {
        values.reserve(static_cast<std::size_t>(n));
        for (int i = 0; i < n; ++i) {
            int v = 0;
            if (!(std::cin >> v)) {
                return 0;
            }
            values.push_back(v);
        }
    }

    int target = 0;
    if (!(std::cin >> target)) {
        return 0;
    }

    for (std::size_t i = 0; i < values.size(); ++i) {
        if (values[i] == target) {
            std::cout << i << '\n';
            return 0;
        }
    }

    std::cout << "NOT FOUND" << '\n';
    return 0;
}

